"""Final safe adversarial review. Record findings; do not repair them in this pass."""
from pathlib import Path
import json,sys
root=Path(__file__).resolve().parents[2];sys.path.insert(0,str(root))
from hinglish_app.caption_audio_alignment import validate_aligned,check_relation
from hinglish_app.caption_native_timing import validate_capture
from hinglish_app.caption_speech_text import caption_tokens
checks=[];findings=[]
def rejected(name,fn):
    try:fn()
    except (ValueError,TypeError):checks.append({'name':name,'passed':True})
    else:
        checks.append({'name':name,'passed':False});findings.append({'name':name,'expected':'Reject invalid input','actual':'Accepted','impact':'Malformed internal timing evidence can pass validation; not generated by normal numeric ASR output.','status':'Reported, intentionally not repaired during final review.'})
rejected('Unrelated script',lambda:check_relation(['garden','plants','flowers'],[],[{'text':'Mumbai won'}],lambda s:s.lower()))
rejected('Conflicting script number',lambda:check_relation(['Mumbai','won','2009'],[{'script_index':0,'alignment':'matched'},{'script_index':1,'alignment':'matched'}],[{'text':'Mumbai'},{'text':'won'},{'text':'2008'}],lambda s:s.lower()))
rejected('Nonfinite direct timestamp',lambda:validate_aligned(['word'],[{'start':float('nan'),'end':1.,'probability':.9}],2))
rejected('Out of media timestamp',lambda:validate_aligned(['word'],[{'start':1.,'end':9.,'probability':.9}],2))
rejected('Reversed direct timestamp',lambda:validate_aligned(['word'],[{'start':1.,'end':.5,'probability':.9}],2))
rejected('Missing aligned word',lambda:validate_aligned(['one','two'],[{'start':0.,'end':.4,'probability':.9}],2))
rejected('Ambiguous overlapping narration',lambda:validate_capture({'duration':3,'unsupported':[],'clips':[{'path':'D:/voice.wav','start':0,'end':2},{'path':'D:/voice.wav','start':1,'end':3}]}))
rejected('Boolean internal timestamp',lambda:validate_aligned(['word'],[{'start':False,'end':True,'probability':.9}],2))
checks.append({'name':'Formatting is not an extra spoken token','passed':len(caption_tokens('Next episode — Rapido ka scam.'))==5})
report={'phase':'Final adversarial review after live native insertion and onset audits','checks':checks,'findings':findings,'scope':'CPU-only validation functions. No app control, inference, file deletion or owner edits.'}
(root/'output/caption-one-general-speech-20261029/final-review.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf8');print(json.dumps({'passed':sum(c['passed'] for c in checks),'total':len(checks),'findings':findings},indent=2))
